    buy_book = []  # List of (price, arrival_time, id, qty)
    sell_book = []  # List of (price, arrival_time, id, qty)
    order_map = {}  # id -> (side, price, qty, arrival_time, index_in_book)
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, qty, arr_time, book_idx = order_map[order_id]
                if side == 'buy':
                    if book_idx < len(buy_book) and buy_book[book_idx][2] == order_id:
                        buy_book.pop(book_idx)
                        # Update indices for all orders after this one
                        for i in range(book_idx, len(buy_book)):
                            oid = buy_book[i][2]
                            if oid in order_map:
                                s, p, q, a, _ = order_map[oid]
                                order_map[oid] = (s, p, q, a, i)
                else:
                    if book_idx < len(sell_book) and sell_book[book_idx][2] == order_id:
                        sell_book.pop(book_idx)
                        # Update indices for all orders after this one
                        for i in range(book_idx, len(sell_book)):
                            oid = sell_book[i][2]
                            if oid in order_map:
                                s, p, q, a, _ = order_map[oid]
                                order_map[oid] = (s, p, q, a, i)
                del order_map[order_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[4] if order_type in ['limit', 'ioc', 'market'] else None
            price = order[3] if order_type in ['limit', 'ioc'] else None

            if order_type == 'market':
                price = float('inf') if side == 'buy' else 0

            remaining_qty = qty

            if side == 'buy':
                # Match against sell_book
                i = 0
                while i < len(sell_book) and remaining_qty > 0:
                    sell_price, sell_arr_time, sell_id, sell_qty = sell_book[i]
                    if sell_price <= price:
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining_qty -= trade_qty
                        sell_book[i] = (sell_price, sell_arr_time, sell_id, sell_qty - trade_qty)

