                                    order_map[oid] = (s, p, q, a, j)
                            del order_map[sell_id]
                        else:
                            s, p, q, a, _ = order_map[sell_id]
                            order_map[sell_id] = (s, p, q, a, i)
                            i += 1
                    else:
                        break

                # Add to buy_book if limit order with remaining qty
                if order_type == 'limit' and remaining_qty > 0:
                    buy_book.append((price, arrival_time, order_id, remaining_qty))
                    order_map[order_id] = ('buy', price, remaining_qty, arrival_time, len(buy_book) - 1)
            else:  # sell
                # Match against buy_book
                i = 0
                while i < len(buy_book) and remaining_qty > 0:
                    buy_price, buy_arr_time, buy_id, buy_qty = buy_book[i]
                    if buy_price >= price:
                        trade_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        remaining_qty -= trade_qty
                        buy_book[i] = (buy_price, buy_arr_time, buy_id, buy_qty - trade_qty)

                        if buy_book[i][3] == 0:
                            buy_book.pop(i)
                            # Update indices
                            for j in range(i, len(buy_book)):
                                oid = buy_book[j][2]
                                if oid in order_map:
                                    s, p, q, a, _ = order_map[oid]
                                    order_map[oid] = (s, p, q, a, j)
                            del order_map[buy_id]
                        else:
                            s, p, q, a, _ = order_map[buy_id]
                            order_map[buy_id] = (s, p, q, a, i)
                            i += 1
                    else:
                        break

                # Add to sell_book if limit order with remaining qty
                if order_type == 'limit' and remaining_qty > 0:
                    sell_book.append((price, arrival_time, order_id, remaining_qty))
                    order_map[order_id] = ('sell', price, remaining_qty, arrival_time, len(sell_book) - 1)

        arrival_time += 1

    return trades

